entries[201398] = { ["name"] = "Mogumozzarella", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 70313 / 5 * 20) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Dieser Käse stammt aus der Zeit vor der Revolution der Pandaren und gehörte zu den wichtigsten Zutaten eines alten Moguleibgerichts: gefüllte Mjampignons.\"\nVerkaufspreis:" }
entries[201399] = { ["name"] = "Urzeitbärrückgrat", ["text"] = "Handwerksmaterial\n\"Ein massiges Rückgrat von den Bären der Dracheninseln.\"\nVerkaufspreis:" }
entries[201400] = { ["name"] = "Wasserschlund", ["text"] = "Handwerksmaterial\n\"Ein massiver, zahniger Kiefer von den großen Fischen, die auf den Dracheninseln heimisch sind.\"\nVerkaufspreis:" }
entries[201401] = { ["name"] = "Schillernde Feder", ["text"] = "Handwerksmaterial\n\"Eine glänzende Feder von Harpyien und großen Vögeln der Dracheninseln.\"\nVerkaufspreis:" }
entries[201402] = { ["name"] = "Großer robuster Oberschenkelknochen", ["text"] = "Handwerksmaterial\n\"Ein schwerer Schenkelknochen von den Brüffelchen, die auf den Dracheninseln heimisch sind.\"\nVerkaufspreis:" }
entries[201403] = { ["name"] = "Mastodonstoßzahn", ["text"] = "Handwerksmaterial\n\"Ein strapazierfähiger Stoßzahn von den Mammuts der Dracheninseln.\"\nVerkaufspreis:" }
entries[201404] = { ["name"] = "Weitschreitersehne", ["text"] = "Handwerksmaterial\n\"Ein Stück faseriges Gewebe, das von den Weitschreitern der Dracheninseln gesammelt wurde.\"\nVerkaufspreis:" }
entries[201405] = { ["name"] = "Büschel Urwolle", ["text"] = "Handwerksmaterial\n\"Ein Büschel flauschiger Wolle von den Riesenwildschafen und Moschushirschen, die auf den Dracheninseln leben.\"\nVerkaufspreis:" }
entries[201406] = { ["name"] = "Leuchtende Titanenkugel", ["text"] = "Handwerksmaterial\n\"Eine geheimnisvolle Kugel, die vor Energie summt und im Besitz eines Titanenhüters auf den Dracheninseln gefunden wurde.\"\nVerkaufspreis:" }
entries[201410] = { ["name"] = "Mächtiges violettes Ding", ["text"] = "Einzigartig\n\"Muss für irgendetwas gut sein... deshalb ist es ja so teuer!\"\nVerkaufspreis:" }
entries[201411] = { ["name"] = "Uraltes Gewölbeartefakt", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses Artefakt scheint aus der Zeit der Inkarnationen zu stammen. Lillian Mondenschein von der Drachenschuppenexpedition würde sich bestimmt für diesen Gegenstand interessieren.\"" }
entries[201412] = { ["name"] = "Uraltes Gewölbeartefakt", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Dieses Artefakt stammt aus der Zeit, als die Inkarnationen gefangen waren. Lillian Mondenschein von der Drachenschuppenexpedition würde sich bestimmt für diesen Gegenstand interessieren.\"" }
entries[201413] = { ["name"] = "Ewigkeitserfüllte Burrata", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Dieser Leckerbissen, der mit Wasser aus dem Brunnen der Ewigkeit zubereitet wurde, war einst ein Leibgericht der Kaldorei. Natürlich vor der Zerschlagung.\"\nVerkaufspreis:" }
entries[201414] = { ["name"] = "Schwingenreißer der Qalashi", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zwingt einen gegnerischen Spielercharakter, der aktuell in der Luft ist, zum Absitzen. Kann nur im Kriegsmodus auf den Dracheninseln eingesetzt werden. (1 Min Abklingzeit)" }
entries[201415] = { ["name"] = "Temporalparmesan", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 70313 / 5 * 20) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Völlig losgelöst von der Zeit hat dieser Parmesan die nette Angewohnheit, sich schon vor der Zubereitung auf der Pasta zu materialisieren.\"\nVerkaufspreis:" }
entries[201416] = { ["name"] = "Brunost des Schwarzen Imperiums", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 70313 / 5 * 20) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Wenn Ihr diesen übel riechenden Käse an Euer Ohr haltet, könnt Ihr ein seltsames Flüstern hören. Der Käse ist außerdem sehr fetthaltig.\"\nVerkaufspreis:" }
entries[201417] = { ["name"] = "Käsebruch aus Stratholme", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 70313 / 5 * 20) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Die ganze Molke muss entsorgt werden! Alles andere ist Käse!\"\nVerkaufspreis:" }
entries[201418] = { ["name"] = "Kugel der Obsidianschuppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Nehmt das Aussehen eines zufälligen Obsidiandrakoniden an. (1 Stunde Abklingzeit)\nVerkaufspreis:" }
entries[201419] = { ["name"] = "Apexis-Asiago", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Der Apexiskristall, der die Rezeptur dieses Käses enthielt und von den Gelehrten der Anhari und Skalaxi perfektioniert wurde, ist längst verloren gegangen.\"\nVerkaufspreis:" }
entries[201420] = { ["name"] = "Gnolans Spezialität des Hauses", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Fleischig und überraschend gut gewürzt, mit einem Hauch von Knorpelknusper.\"\nVerkaufspreis:" }
entries[201421] = { ["name"] = "Tuskarrdörrfleisch", ["text"] = "\"Ist das...?\"\nVerkaufspreis:" }
entries[201422] = { ["name"] = "Blitzgefrorenes Fleisch", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 70313 / 5 * 20) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Gefroren auf dem Höhepunkt der Frische.\"\nVerkaufspreis:" }
entries[201423] = { ["name"] = "Gruselhelm", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Setzt die Maske auf Euer Gesicht oder Euren Helm.\nBenötigt Schlotternächte" }
entries[201424] = { ["name"] = "Unbrauchbares Pflanzenmaterial", ["text"] = "Verkaufspreis:" }
entries[201425] = { ["name"] = "Gelber Kriegsottuk", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 30 bei den Tuskarr von Iskaara.\n\n\"Die gelben Ottuks des Azurblauen Gebirges sind schlank, listig und klug. Jene, die für den Krieg ausgebildet wurden, sind die edelsten Kavalleriereittiere der Tuskarr und zu Land und zu Wasser gleichermaßen tauglich.\"\nFraktion:\nTuskarr von Iskaara\nRuhmstufe:\n30\nVerkäufer:\nTatto\nOrt:\nIskaara\nKosten:\n5\n5\n1.000" }
entries[201426] = { ["name"] = "Brauner Kriegsottuk", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 30 bei den Tuskarr von Iskaara.\n\n\"Die Tuskarr von Iskaara verabscheuen den Krieg, doch viele der Tuskarr und ihrer Verbündeten haben dennoch mit einem Kriegsottuk an ihrer Seite den Speer ergriffen.\"\nFraktion:\nTuskarr von Iskaara\nRuhmstufe:\n30\nVerkäufer:\nTatto\nOrt:\nIskaara\nKosten:\n5\n5\n1.000" }
entries[201427] = { ["name"] = "Flüchtige Sande", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Ein Hauch Zeitmagie, um Euch in Schwung zu bringen!\n\nErhöht die Bewegungsgeschwindigkeit 5 Sek. lang um 250%. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[201428] = { ["name"] = "Quecksilbersande", ["text"] = "Einzigartig (20)\nBenutzen: Die Sande lassen Euch Zeit borgen, aber fordern sie später zurück.\n\nBewegungsgeschwindigkeit 10 Sek. lang um 200% erhöht, aber danach 10 Sek. lang um 90% verringert. (1 Min Abklingzeit)\nVerkaufspreis:" }
