entries[201436] = { ["name"] = "Zeitgefangene Sande", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Wendet die Sicherheitsmaßnahmen des temporalen Konflux auf Euch selbst an!\n\nIhr seid 5 Min. lang in einer Blase gefangen. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
