entries[201438] = { ["name"] = "Müde Sande", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Verlangsamt Euren Körper, indem er das Gewicht der Zeit selbst trägt.\n\nBewegungsgeschwindigkeit 1 Min. lang um 50% verringert.\nVerkaufspreis:" }
entries[201439] = { ["name"] = "Erneuerter Traum", ["text"] = "Wird beim Aufheben gebunden\n\"Ein kleiner Traum, der durch Euer Handeln wieder vollständig ist.\"\n<Zum Öffnen rechtsklicken>" }
entries[201440] = { ["name"] = "Zügel des befreiten Slyvern", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Es ist schwer zu erkennen, weil er viel zu wütend ist, aber dieser Slyvern ist eigentlich froh, dass er nicht mehr den Gnollen gehört.\"\nBeute:\nBrisenbiss\nZone:\nAzurblaues Gebirge" }
