entries[201449] = { ["name"] = "Wildheitsabzeichen des blutroten Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 315.\nBenutzen: Erhöht den Primärwert 15 Sek. lang um 593 . (1 Min Abklingzeit)\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[201450] = { ["name"] = "Medaillon des blutroten Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+224 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Entfernt alle bewegungseinschränkenden und Kontrollverlusteffekte.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[201451] = { ["name"] = "Inbrunstinsigne des blutroten Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 315.\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren Primärwert für 20 Sek. um 500 zu erhöhen.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[201452] = { ["name"] = "Emblem des blutroten Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+224 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Erhöht 15 Sek. lang die maximale Gesundheit um 28689 . (2 Min Abklingzeit)\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[201453] = { ["name"] = "Siegel der Anpassung des blutroten Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+224 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Entfernt alle Effekte mit einer Dauer von 5 Sek. oder mehr, die Kontrollverlust bewirken. Dieser Effekt kann nur einmal alle 1 Min. auftreten.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[201454] = { ["name"] = "Temperamentvolle Himmelskralle", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Slyvern fühlen sich als Reittiere meist nicht wohl. Nur, wer gewillt ist, ihrem unstillbaren Appetit nachzukommen und ein wachsames Auge auf sie zu haben, sollte dennoch versuchen, sie zu reiten.\"\nVerkäufer:\nZon'Wogi\nZone:\nAzurblaues Gebirge" }
