entries[201697] = { ["name"] = "Kaltarrakühlbräu", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 93750 / 5 * 20) Mana wieder her.\nIhr müsst beim Trinken sitzen bleiben.\n\"Eine Spezialität des blauen Drachenschwarms. Hat irgendwie immer die perfekte Temperatur.\"\nVerkaufspreis:" }
