entries[201702] = { ["name"] = "Purpurvorquin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Dracthyr und ehrfürchtigen Ruf bei den Obsidianwächtern (Allianz) oder ehrfürchtigen Ruf bei den Dunkelkrallen (Horde).\nVerkaufspreis:\n\"Diese edlen Kreaturen werden für ihre Widerstandskraft im Kampf geschätzt, selbst gegen Drachenfeuer. So stellen sie die kostbaren Reittiere der Dracthyrkavallerie.\"\nVerkäufer:\nTreysh\nZone:\nVerbotene Insel\nKosten:\n\nVerkäufer:\nTethalash\nZone:\nValdrakken\nKosten:" }
entries[201703] = { ["name"] = "Pinkie", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
