entries[201788] = { ["name"] = "Boshafter Säbelzahn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man einen boshaften Säbelzahn beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Eliteeinheiten der Horde, die diese Säbelzahnreittiere nutzen, verwenden einen Schlachtruf, der aus dem Thalassischen in etwa mit \"pspspspsps\" übersetzt werden könnte.\"\nPvP:\nDragonflight: Saison 1\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder" }
entries[201789] = { ["name"] = "Boshafter Säbelzahn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man einen boshaften Säbelzahn beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Eliteeinheiten der Allianz, die diese Säbelzahnreittiere nutzen, verwenden einen Schlachtruf, der aus dem Darnassischen in etwa mit \"Hierher, miez, miez\" übersetzt werden könnte.\"\nPvP:\nDragonflight: Saison 1\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder" }
entries[201790] = { ["name"] = "Erneuerter Protodrache: Verkörperung der Sturmfresserin", ["text"] = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den erneuerten Protodrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
entries[201791] = { ["name"] = "Drachkinzähmen leicht gemacht", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lest das Buch noch einmal, um zu lernen, wie man mit niederen Drachkin Freundschaft schließt. (1s Abklingzeit)\n\"Es braucht das Wissen von Drachen, um ihre Verwandten zu zähmen.\"" }
entries[201792] = { ["name"] = "Hochlanddrache: Verkörperung des blutroten Gladiators", ["text"] = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den Hochlanddrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
entries[201793] = { ["name"] = "Prunkvoller Edelstein", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein kurioser Schatz aus Valdrakkens Großer Schatzkammer.\"" }
entries[201794] = { ["name"] = "Bauplan: Ruhiger mechanischer Yeti", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen ruhigen mechanischen Yeti herstellt.\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:\nRuhiger mechanischer Yeti\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren ruhigen mechanischen Yeti beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:\nBenötigt Geschmeidiger unverwüstlicher Balg , Thoriumapparat (4), Kugel des Wassers (2), Echtsilberumwandler (2), Goldkraftkern" }
entries[201795] = { ["name"] = "Klaue der Valdrakkenwache", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Faustwaffe\n1 - 2 Schaden Geschwindigkeit 3.60\n(0.4 Schaden pro Sekunde)\nBenötigt Ruhmrang 29 beim Valdrakkenabkommen.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[201796] = { ["name"] = "Klaue des Valdrakkendrakoniden", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Faustwaffe\n1 - 2 Schaden Geschwindigkeit 3.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 20 / 20\nBenötigt Ruhmrang 29 beim Valdrakkenabkommen.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
