entries[201807] = { ["name"] = "Wildheitsabzeichen des blutroten Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 438.\nBenutzen: Erhöht den Primärwert 15 Sek. lang um 870 . (1 Min Abklingzeit)\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[201808] = { ["name"] = "Inbrunstinsigne des blutroten Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 438.\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren Primärwert für 20 Sek. um 735 zu erhöhen.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[201809] = { ["name"] = "Emblem des blutroten Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+329 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Erhöht 15 Sek. lang die maximale Gesundheit um 63040 . (2 Min Abklingzeit)\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[201810] = { ["name"] = "Medaillon des blutroten Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+329 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Entfernt alle bewegungseinschränkenden und Kontrollverlusteffekte.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[201811] = { ["name"] = "Siegel der Anpassung des blutroten Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Medaillons des Gladiators (1)\nSchmuck\n+329 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Entfernt alle Effekte mit einer Dauer von 5 Sek. oder mehr, die Kontrollverlust bewirken. Dieser Effekt kann nur einmal alle 1 Min. auftreten.\n\nAuszeichnung des Gladiators (0/2)\nEmblem des Gladiators\nMedaillon des Gladiators\n(2) Set : Erhöht in Arenen, auf Schlachtfeldern und im Kriegsmodus Eure Hauptwert um 12% und Eure Ausdauer um 20%.\nVerkaufspreis:" }
entries[201813] = { ["name"] = "Verdorbener Feuerwein", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 56250 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\nVerkaufspreis:" }
entries[201815] = { ["name"] = "Umhang der vielen Gesichter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Die Rückseite dieses Umhangs wird von Gesichtern geziert, deren Erscheinung sich Eurem Blick wieder entzieht, sobald Ihr sie bemerkt. (30 Min Abklingzeit)\nVerkaufspreis:" }
