entries[201817] = { ["name"] = "Zwielichtschatz", ["text"] = "Wird beim Aufheben gebunden\n\"Beinhaltet Gold, Vorräte der Dracheninseln, seltene Dracheninselartefakte und Relikte der Titanen sowie eine Chance auf kosmetische Primalistenwaffen und -rüstungen.\"\n<Zum Öffnen rechtsklicken>" }
