entries[201820] = { ["name"] = "Schweizer Silithus", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Es gibt nur ein einziges großes Loch in der Mitte, aus dem ein lächerlich großer Zahnstocher herausragt. Habt Ihr etwa ein Schwert oder so etwas in der Art erwartet?\"\nVerkaufspreis:" }
entries[201821] = { ["name"] = "Professor Dozentaurs Gehirn über die Dracheninseln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Setzt Eure Stufe in den von Euch erlernten Handwerksfertigkeiten der Dracheninseln auf das Maximum und lehrt Euch alle dazugehörigen Rezepte. (2 Min Abklingzeit)\n\"Und jetzt wisst Ihr, warum Juniorprofessor Dozentaur Euch die ganze Zeit geholfen hat.\"" }
