entries[201927] = { ["name"] = "Schimmernder Arkanokristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Im Licht manifestiert dieser Kristall arkane Schönheit und zerlegt sie in ihre Bestandteile. (2 Min Abklingzeit)\n\"Bieten sowohl Neuartiges als auch unbewusstes Verstehen. Ich verstehe jetzt, was mit arkanen Künsten gemeint ist.\"" }
entries[201928] = { ["name"] = "Windgebettalisman der Ohn'ir", ["text"] = "Einzigartig\n\"Ein ungewöhnliches Anbetungselement der Ohn'ir, allerdings nicht von Natur aus heilig. Wird sehr selten mit Fremden geteilt.\"\nVerkaufspreis:" }
entries[201929] = { ["name"] = "Geraubter Atem von Ohn'ahra", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nVerkaufspreis:" }
entries[201930] = { ["name"] = "H.I.L.F.E.", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Verschießt ein Signalleuchtfeuer, um Verbündete in der Nähe vor drohender Gefahr zu warnen.\n\nKann nur auf Schlachtfeldern verwendet werden. In einem Bereich kann von derselben Fraktion nur einmal alle 3 Min. ein Signalleuchtfeuer verschossen werden. (2 Min Abklingzeit)\n\"Hallo Ihr, lebe für Errettung!\"\nVerkaufspreis:" }
entries[201931] = { ["name"] = "Warcraft Rumble-Spielzeug: Maiev", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Werft Euer Warcraft Rumble-Miniatur: Maiev in den Ring. (1 Min Abklingzeit)" }
entries[201933] = { ["name"] = "Herausforderungspuppe des schwarzen Drachen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Beschwört eine Herausforderungspuppe des schwarzen Drachen am Zielort, die 5 Min. lang bestehen bleibt. Diese dient als Zielattrappe und kann von der jeweils entgegengesetzten Rolle geheilt werden oder Schaden durch sie erleiden, solange sie bestehen bleibt. Wird sie leben oder sterben?\n\nKann nur im Freien eingesetzt werden. (1 Stunde Abklingzeit)" }
