entries[202018] = { ["name"] = "Unversehrter Schreiberstock", ["text"] = "Wird beim Aufheben gebunden\n\"Furbolgs zeichnen alles auf solchen Stöcken auf, von historischen Ereignissen bis zu banalen Handelsgeschäften. Dazu schnitzen sie die kurzen Striche ihrer Schriftsprache direkt ins Holz. Sonova Schneeweh wäre an einem Fund dieses Ausmaßes überaus interessiert.\"\nVerkaufspreis:" }
entries[202019] = { ["name"] = "Goldener Drachenkelch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Zeigt Euren Reichtum der Welt und hinterlässt eine Spur aus Reichtümern. (30 Sek. Abklingzeit)\n\"Aber schmeckt sie auch nach Gold...?\"" }
entries[202020] = { ["name"] = "Jagdsturm", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört einen Sturm, der ein verbündetes Ziel verfolgt! (5 Min Abklingzeit)" }
entries[202021] = { ["name"] = "Siegesflagge des Verwüsters", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert auf der Leiche eines gegnerischen Spielercharakters vor Euch eine Flagge. (1 Min Abklingzeit)" }
entries[202022] = { ["name"] = "Yennus Drachen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Lässt Yennus Drachen steigen. (1 Stunde Abklingzeit)" }
entries[202023] = { ["name"] = "Lebensfunke", ["text"] = "Questgegenstand\n\"Diese schillernde Essenz ist ein Beweis für die Wiederauferstehung der Dracheninseln.\"" }
entries[202024] = { ["name"] = "\"Langes Messer\"", ["text"] = "Questgegenstand\n\"Eine der langen Krallen des Raptors Gor'krosh.\"" }
entries[202025] = { ["name"] = "Fass mit Ahnenaltbier", ["text"] = "Questgegenstand\n\"Ein Fass besten Kriegspfadbräus.\"" }
entries[202026] = { ["name"] = "Uferkrabbe aus Durotar", ["text"] = "Questgegenstand\n\"Eine wilde Krabbe, die an der Küste Durotars in der Nähe der Echoinseln gefangen wurde.\"" }
entries[202027] = { ["name"] = "Frisches Talbuksteak", ["text"] = "Questgegenstand\n\"Frisches Fleisch von Talbuks der Scherbenwelt. Sie wurden extra für das Kosh'harg importiert.\"\nVerkaufspreis:" }
entries[202028] = { ["name"] = "Südstromlachs", ["text"] = "Questgegenstand\n\"Frisch gefangener Lachs aus dem Südstrom.\"\nVerkaufspreis:" }
entries[202029] = { ["name"] = "Inselzitrone", ["text"] = "Questgegenstand\n\"Zitronen von den Echoinseln. Saftig sauer!\"\nVerkaufspreis:" }
entries[202030] = { ["name"] = "Gemahlener Gorgrondpfeffer", ["text"] = "Questgegenstand\n\"Gemahlene Pfefferkörner von den Bäumen des Schergrats.\"\nVerkaufspreis:" }
entries[202031] = { ["name"] = "Farahlonbockshorn", ["text"] = "Questgegenstand\n\"Ein Kraut, das einst vom Klan des Lachenden Schädels geschätzt wurde. Mittlerweile wird es in den Biokuppeln des Nethersturms angebaut.\"\nVerkaufspreis:" }
entries[202032] = { ["name"] = "Festmahl für die Ahnen", ["text"] = "Questgegenstand\n\"Ein Festmahl kulinarischer Leckerbissen sowohl Draenors als auch Azeroths. Eine würdige Opfergabe für die geehrten Toten.\"" }
entries[202033] = { ["name"] = "Schlüpfriger Lachs", ["text"] = "Dauer: 1 Stunde\nBenutzen: Stellt 5 Sek. lang pro Sekunde 20% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nWarnung: Kann zu Aufgeregtheit führen.\n\"Esst ihn lieber rasch, bevor er Euch entschlüpft!\"" }
entries[202034] = { ["name"] = "Flamme der Erinnerung", ["text"] = "Anima\nWird beim Aufheben gebunden\nBenutzen: Lagert 35 gespeicherte Anima im Animareservoir Eures Pakts ein.\nVerkaufspreis:" }
entries[202035] = { ["name"] = "Selbstwärmende Rationen", ["text"] = "Wird beim Aufheben gebunden\nDauer: 1 Stunde (Realzeit)\nBenutzen: Entfernt 5 Stapel von 'Eiskalt'.\n\"Rationen, die mit elementarer Macht erfüllt sind, um die Körpertemperatur zu regulieren und Gesundheit wiederherzustellen.\"\nVerkaufspreis:" }
entries[202037] = { ["name"] = "Schaufel oder Mehrzweckwerkzeugkasten der Expedition" }
entries[202039] = { ["name"] = "Essenz des Sturms", ["text"] = "Wird beim Aufheben gebunden\n\"Ein kleiner Überrest des Sturms in der Zukunft der Primalisten. Kann verwendet werden, um Gegenstände von Brendormi in der Zukunft der Primalisten zu erhalten.\"" }
entries[202042] = { ["name"] = "Wasserschemen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Setzt eine schwarze Tauchersonnenbrille auf.\n\"Gleich in mehrerer Hinsicht \"cool\".\"" }
entries[202044] = { ["name"] = "Kristallfokusfragment", ["text"] = "Questgegenstand\nEinzigartig (8)\n\"Selbst zerschmettert pulsiert dieses Kristallfragment vor arkaner Macht.\"" }
entries[202046] = { ["name"] = "Tortollanischer Glücksbringer", ["text"] = "Einzigartig\nBenutzen: Teleport zur Sucherwarte an der Juwelenscheinküste in Sturmsang. (1 Stunde Abklingzeit)\n\"Könnte Euch helfen, schwierige Aufgaben zu meistern.\"\nVerkaufspreis:" }
entries[202047] = { ["name"] = "Schimmernde Donnersteininkarnation", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erfüllt Eure Rüstung mit einem schwachen Echo der Macht der Sturmfresserin, wodurch Ihr zusätzliche optische Effekte für bestimmte Klassensetvorlagen des Gewölbes der Inkarnationen freischaltet.\n\nDieser Effekt gilt für die gesamte Kriegsmeute." }
entries[202061] = { ["name"] = "Leeres Fischfass", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Füllt das Fass." }
entries[202062] = { ["name"] = "Aschefeder", ["text"] = "Wird beim Aufheben gebunden\n\"Von den verschiedenen Phönixen auf den Lavafeldern nahe der Obsidianzitadelle.\"\nVerkaufspreis:" }
entries[202063] = { ["name"] = "Zappelnder Buntbarsch", ["text"] = "Dauer: 1 Stunde\nBenutzen: Stellt 5 Sek. lang pro Sekunde 20% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nWarnung: Kann zu Aufgeregtheit führen.\n\"Esst ihn lieber rasch, bevor er Euch entschlüpft!\"" }
entries[202064] = { ["name"] = "Kriegsbanner des Zorns", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert Euer Kriegsbanner für 2 Min. am Zielort. Gruppenmitglieder innerhalb von 40 Metern um das Banner haben einen um 5% erhöhten Primärwert. Kann nur auf den Dracheninseln verwendet werden." }
