entries[202066] = { ["name"] = "Halbvolles Fischfass", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Füllt das Fass." }
entries[202068] = { ["name"] = "Randvolles Fischfass", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Füllt das Fass." }
entries[202069] = { ["name"] = "Übervolles Fischfass", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bringt das Fass dorthin zurück, wo Ihr es gefunden habt." }
entries[202070] = { ["name"] = "Außergewöhnliches Fell", ["text"] = "\"Handwerker wie Sammler zugleich sehnen sich nach diesem strahlenden und prachtvollen Pelz.\"\nVerkaufspreis:" }
