entries[202074] = { ["name"] = "Königsfinne, der weise Schnurrwels", ["text"] = "Wird beim Aufheben gebunden" }
entries[202079] = { ["name"] = "Truhe mit Schätzen des Gewölbes", ["text"] = "Wird beim Aufheben gebunden\n\"Gewährt ein Ausrüstungsteil für Eure Beutespezialisierung.\"\n<Zum Öffnen rechtsklicken>" }
entries[202080] = { ["name"] = "Truhe mit Schätzen des Gewölbes", ["text"] = "Heroisch\nWird beim Aufheben gebunden\n\"Gewährt ein Ausrüstungsteil für Eure Beutespezialisierung.\"\n<Zum Öffnen rechtsklicken>" }
entries[202081] = { ["name"] = "Vorratstasche der Dracheninseln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Verschiedene Ressourcen und Baumaterialien, die verbündeten Fraktionen auf den Dracheninseln im Kampf gegen die Primalisten helfen können. Wird zum Kauf von Gegenständen verwendet, die über die Ruhmstufe freigeschaltet werden.\"" }
entries[202082] = { ["name"] = "Versteinertes Drachenei", ["text"] = "Wird beim Aufheben gebunden\n\"Irgendetwas hat dieses Ei vor langer Zeit erschrocken.\"" }
entries[202084] = { ["name"] = "Erodiertes Fossil", ["text"] = "Wird beim Aufheben gebunden\n\"Wasser und Zeit haben diese vergessene Kreatur freigelegt.\"" }
entries[202085] = { ["name"] = "Käferbeißerschildkröte", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[202086] = { ["name"] = "Drache des blutroten Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\"Lehrt Euch, wie man dieses Reittier beschwört.\"\n\n\"Geschmiedet in den Feuern der Eroberung und bis an die Zähne bewaffnet.\"\nErfolg:\nGladiator: Saison 1 von Dragonflight\nKategorie:\nSpieler gegen Spieler" }
entries[202087] = { ["name"] = "Entfernungsset des Tüftlers", ["text"] = "Wird bei Benutzung gebunden\nBenutzen: Entfernt gewagt, aber dennoch effektiv, ein Tüfteleimodul aus seinem Sockel zum späteren Gebrauch.\n\"Es ist nur ein Schraubenzieher... Viel Glück!\"\nVerkaufspreis:" }
entries[202088] = { ["name"] = "Machtvolles Fläschchen der Erneuerung", ["text"] = "Herbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nDauer: 2 std. (Realzeit)\nBenutzen: Stellt 30% Gesundheit wieder her. (5 Min Abklingzeit)\n\"Nach all den Jahren immer noch wirksam.\"" }
entries[202089] = { ["name"] = "Prestigeträchtiger Umhang des blutroten Gladiators", ["text"] = "Wird beim Aufheben gebunden\nRücken\n9 Rüstung\n+9 [Beweglichkeit oder Stärke oder Intelligenz]\n+13 Ausdauer\nErhöht Eure Tempowertung um + 9.\nErhöht Eure Meisterschaftswertung um + 9.\nVerkaufspreis:" }
entries[202090] = { ["name"] = "Wappenrock des blutroten Gladiators", ["text"] = "Saison 1 von Dragonflight\nWird beim Aufheben gebunden\nWappenrock\nErlangt den Rang Elite in Saison 1 von Dragonflight.\nVerkaufspreis:" }
entries[202091] = { ["name"] = "Insigne der Drachenschuppenexpedition", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Gewährt 2500 Ruf bei der Drachenschuppenexpedition. (2 Sek. Abklingzeit)" }
entries[202092] = { ["name"] = "Insigne der Tuskarr von Iskaara", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Gewährt 2500 Ruf bei den Tuskarr von Iskaara. (2 Sek. Abklingzeit)" }
entries[202093] = { ["name"] = "Insigne des Valdrakkenabkommens", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Gewährt 2500 Ruf beim Valdrakkenabkommen. (2 Sek. Abklingzeit)" }
entries[202094] = { ["name"] = "Insigne der Zentauren der Maruuk", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Gewährt 2500 Ruf bei den Zentauren der Maruuk. (2 Sek. Abklingzeit)" }
entries[202096] = { ["name"] = "Waffen der Schuppe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Rüstet einen Widerstandsverteidiger der Zeitwanderer mit Waffen aus, die bei schweren Verletzungen Gesundheit wiederherstellen und eine Chance gewähren, Ziele zu betäuben.\n\nKann nur bei einem Widerstandsverteidiger der Zeitwanderer innerhalb der Zukunft der Primalisten während des Ereignisses \"Der Zorn des Sturms\" verwendet werden.\nVerkaufspreis:" }
entries[202097] = { ["name"] = "Massige Kiste voller Tierhäute und Schuppen", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[202098] = { ["name"] = "Vollgepackte Kiste mit Abbaumaterialien", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[202099] = { ["name"] = "Lagersack mit Heilkräutern", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[202100] = { ["name"] = "Großer Haufen abgelegter Stoffe", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[202101] = { ["name"] = "Umgekippter Haufen entzauberter Überreste", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[202102] = { ["name"] = "Makelloser Flunkschatzbeutel", ["text"] = "Wird beim Aufheben gebunden\n\"Wie der so sauber bleiben konnte, ist Euch ein Rätsel.\"\n<Zum Öffnen rechtsklicken>" }
entries[202105] = { ["name"] = "Rostige Münze der Inseln", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Eine einfache, rostige Münze, die die Vorderseite eines Drachen zeigt.\"\nVerkaufspreis:" }
entries[202106] = { ["name"] = "Zerkautes Stück eines Tagebuchs", ["text"] = "Questgegenstand\n\"Die Notizen sind feucht, zerrissen und kaum lesbar. Doch ein paar Fetzen sind noch intakt.\"" }
entries[202107] = { ["name"] = "Schattenbekritzelte Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Die Münze birgt eine gespenstische Ausstrahlung. Ihre Oberfläche ist von dunkelvioletten und blauen Linien aus magischer Energie durchzogen.\"\nVerkaufspreis:" }
entries[202108] = { ["name"] = "Lebhafter Barsch", ["text"] = "Dauer: 1 Stunde\nBenutzen: Stellt 5 Sek. lang pro Sekunde 20% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nWarnung: Kann zu Aufgeregtheit führen.\n\"Esst ihn lieber rasch, bevor er Euch entschlüpft!\"" }
entries[202112] = { ["name"] = "Kristallzerschmetternde Waffen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Rüstet einen Widerstandsverteidiger der Zeitwanderer mit einer Waffe aus, die sein Ziel regelmäßig betäubt.\n\"Waffen, die stark genug sind, um makellose Kristalle zu zerschmettern.\"\nVerkaufspreis:" }
entries[202116] = { ["name"] = "Lebhafter Alchemistenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)\nSchmuck\nErhöht Eure Tempowertung um + 508.\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren Primärwert für 10 Sek. um 956 zu erhöhen und die Abklingzeit Eurer Gefechtstränke um 10 Sek. zu verringern.\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
entries[202117] = { ["name"] = "Band des Konventbewahrers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Kobaltring der Macht (1)\nFinger\n+532 Ausdauer\nErhöht Eure kritische Trefferwertung um + 304.\nErhöht Eure Tempowertung um + 287.\nAnlegen: Eure Heilzauber haben eine Chance, Eure Verbündeten mit arkaner Magie zu heilen und zusätzlich 41087 Gesundheit wiederherzustellen.\nBenötigt ein hohes Energieniveau des Kobaltkonvents.\nVerkaufspreis:" }
entries[202118] = { ["name"] = "Ring des Konventwächters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Kobaltring der Macht (1)\nFinger\n+532 Ausdauer\nErhöht Eure kritische Trefferwertung um + 304.\nErhöht Eure Tempowertung um + 287.\nAnlegen: Beim Erleiden von Schaden besteht die Chance, einen arkanen Schild zu erhalten, der die nächsten 76646 Schaden absorbiert und 12 Sek. lang bestehen bleibt.\nBenötigt ein hohes Energieniveau des Kobaltkonvents.\nVerkaufspreis:" }
entries[202119] = { ["name"] = "Reif des Konventgelehrten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Kobaltring der Macht (1)\nFinger\n+532 Ausdauer\nErhöht Eure kritische Trefferwertung um + 304.\nErhöht Eure Tempowertung um + 287.\nAnlegen: Eure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, 27374 Arkanschaden zu verursachen.\nBenötigt ein hohes Energieniveau des Kobaltkonvents.\nVerkaufspreis:" }
entries[202122] = { ["name"] = "Urzeitliche Chaosansammlung", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält 10 Einheiten urzeitliches Chaos.\"\n<Zum Öffnen rechtsklicken>" }
