entries[202238] = { ["name"] = "Vollstrecker Grants Siegel", ["text"] = "Questgegenstand\n\"Ein einfacher Ring aus miteinander verflochtenem Metall und einem kleinen Stein, der merkwürdigerweise auf der Innenseite eingefasst ist.\"" }
entries[202239] = { ["name"] = "Altes Zauberbuch von Senegos", ["text"] = "Questgegenstand\n\"Eines der vielen alten Zauberbücher von Senegos.\"" }
entries[202240] = { ["name"] = "Foliant der fantastischen Sphären", ["text"] = "Questgegenstand\n\"Dieser Foliant beschreibt die fantastischen Methoden, um Sphären mit arkaner Magie zu kombinieren.\"" }
entries[202241] = { ["name"] = "Foliant des Rollens", ["text"] = "Questgegenstand\n\"Dieser Foliant beschreibt, wie man ein Objekt dazu bringt, entgegen physikalischer Grenzen, mit hoher Geschwindigkeit zu rollen.\"" }
entries[202242] = { ["name"] = "Foliant des Klebens", ["text"] = "Questgegenstand\n\"Dieser Foliant beschreibt, wie man verschiedene Kreaturen dazu bringt, an Teilen von beschworenen arkanen Formen zu kleben.\"" }
entries[202243] = { ["name"] = "Honigfrosthonig", ["text"] = "Questgegenstand\n\"Dank seines hohen Zuckergehalts friert er selbst im bittersten Winter nicht ein. Das macht ihn auch perfekt, um Hochprozentiges daraus zu brauen.\"" }
entries[202244] = { ["name"] = "Frostiger Futtervorrat", ["text"] = "Questgegenstand\n\"Eine Sammlung aus Beeren, Fleisch, Nüssen und Knollen, die in allen Teilen der Oberen Frostlande gesammelt wurden. Die bittere Kälte hat sie haltbar gemacht.\"" }
entries[202245] = { ["name"] = "Rostkieferzapfen", ["text"] = "Questgegenstand\n\"Die bemerkenswert robusten Zapfen kommen mit allen Elementen in Berührung. So repräsentieren sie das Gleichgewicht der Natur und dienen als Symbol für Erneuerung.\"" }
entries[202246] = { ["name"] = "Winterpelzschmuck", ["text"] = "Questgegenstand\n\"Die vielfältigen Stücke aus Halbedelsteinen, Andenken und Trophäen bemerkenswerter Jagden sind allesamt mit Runen in der Winterpelzsprache versehen, die jedes Stück eindeutig kennzeichnen wie ein Fingerabdruck.\"" }
entries[202247] = { ["name"] = "Technoseher", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Filtert nach Abstimmungsgegenständen und Orten. (3 Sek. Abklingzeit)" }
entries[202248] = { ["name"] = "Eisiger Schatten", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Schwert\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\n\"Aus den vergessenen Tiefen des Nexus gezogen, strahlt diese Klinge eine beißende Kälte aus.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[202249] = { ["name"] = "Rezept: Golddorntee", ["text"] = "Benutzen: Lehrt Euch, wie man Golddorntee mischt.\nBenötigt Klassische Kochkunst (160)\nVerkaufspreis:\nGolddorntee\nBenutzen: Stellt im Verlauf von 27 Sek. insgesamt ( 50 / 5 * 27) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\nVerkaufspreis:\nBenötigt Golddorn , Erfrischendes Quellwasser" }
entries[202250] = { ["name"] = "Süße Knallblumenblüte", ["text"] = "Questgegenstand\n\"Aus den Blättern dieser Blüte lässt sich ein wunderbar leichter und duftender Tee brauen.\"" }
entries[202252] = { ["name"] = "Rezeptratte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Versucht, gesittet mit der gefangenen Ratte zu verhandeln, um an ihr streng gehütetes Rezept zu kommen. (5 Min Abklingzeit)" }
