entries[202264] = { ["name"] = "Verteidiger der Winterpelze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+371 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Beim Einsatz von Zaubern und Fähigkeiten besteht eine geringe Chance, einen Winterpelzverteidiger herbeizurufen, der 30 Sek. lang an Eurer Seite kämpft. (31s Abklingzeit)\nVerkaufspreis:" }
entries[202265] = { ["name"] = "Käserad Welpenflüsterbrie", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein leichter, buttriger Käse mit einem Hauch Nussaroma.\"" }
entries[202266] = { ["name"] = "Beutel mit würzigen Haustierhappen", ["text"] = "Questgegenstand\nEinzigartig\n\"Nur Haustiere in ausgeprägt robuster körperlicher Verfassung können diese Happen vertragen.\"" }
entries[202267] = { ["name"] = "Clessingtonsiegel", ["text"] = "Questgegenstand\n\"Eine seltsame Kombination aus vier unterschiedlichen Siegeln, die so verdreht sind, dass sie zusammen ein einziges bilden. Aus dem Inneren strahlt neben dem bekannten scharfen Geruch von Arkanmagie ein bisschen Wärme.\"" }
entries[202268] = { ["name"] = "Winterpelztotem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+361 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Beschwört ein Winterpelztotem am Zielort, das 20 Sek. lang anhält. Gruppenmitglieder innerhalb von 10 Metern haben eine hohe Chance, mit schädlichen Zaubern und Fähigkeiten 13405 zusätzlichen Naturschaden zu verursachen.\n\nDer zusätzliche Schaden erhöht sich, wenn der betroffene Verbündete ein Furbolg ist. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[202271] = { ["name"] = "Beutel voller Goldmünzen", ["text"] = "Questgegenstand\nBenutzen: Wirft eine Münze zu einer angeheuerten Leibwache. (3 Sek. Abklingzeit)" }
entries[202273] = { ["name"] = "Erneuerter Protodrache: Kurzschnauze", ["text"] = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den erneuerten Protodrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird.\nErfordert einen wohlwollenden Ruf bei den Winterpelzfurbolgs mit mindestens einem Charakter in Eurer Kriegsmeute." }
