entries[202281] = { ["name"] = "Goldbarren", ["text"] = "Questgegenstand\n\"Mehr Gold!\"" }
entries[202282] = { ["name"] = "Winterpelzheilungstotem", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n245 - 316 Schaden Geschwindigkeit 2.60\n(107.9 Schaden pro Sekunde)\n+1.106 Intelligenz\n+497 Ausdauer\n+ 185 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 143.\nHaltbarkeit 90 / 90\nBenutzen: Schlägt mit dem Totem auf die Wunde eines Verbündeten, was diesen für kurze Zeit betäubt und um 51410 Gesundheit heilt.\n\nKann nur im Freien verwendet werden. (2 Min Abklingzeit)\nErfordert einen wohlwollenden Ruf bei den Winterpelzfurbolgs mit mindestens einem Charakter in Eurer Kriegsmeute.\n\"Prügelt Euren Verbündeten wieder Leben in den Leib.\"\nVerkaufspreis:" }
entries[202283] = { ["name"] = "Lesebrille", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Setzt eine Lesebrille auf. (3 Min Abklingzeit)\n\"Verleiht ein gebildetes Aussehen.\"\nVerkaufspreis:" }
entries[202284] = { ["name"] = "Abgenutzter Messingschlüssel", ["text"] = "Questgegenstand\n\"Am Ende des Schlüssels befindet sich ein glitzerndes Smaragdbaguette.\"" }
entries[202286] = { ["name"] = "Wärmende Kohle", ["text"] = "Questgegenstand\n\"Ein Stück Kohle, das vor Hitze strahlt.\"" }
entries[202287] = { ["name"] = "Pfotengemachte Winterpelzreagenzientasche", ["text"] = "Wird an Kriegsmeute gebunden\n34 Platz Reagenzientasche\nVerkaufspreis:" }
entries[202288] = { ["name"] = "Obsidianedelstein", ["text"] = "Questgegenstand\n\"Ein schimmernder Kristall, stellvertretend für die Hoffnung auf die Zukunft des schwarzen Drachenschwarms.\"" }
entries[202289] = { ["name"] = "Rezept: Feuerwassersorbet", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein Feuerwassersorbet zubereitet.\nRezept für 5 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab.\nBenötigt Kochkunst der Dracheninseln (1)\nErfordert einen respektvollen Ruf bei den Winterpelzfurbolgs mit mindestens einem Charakter in Eurer Kriegsmeute.\nVerkaufspreis:" }
entries[202290] = { ["name"] = "Feuerwassersorbet", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 80357 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt, was alle Sekundärwerte um 18 sowie Eure Größe erhöht.\nVerkaufspreis:" }
