entries[202314] = { ["name"] = "Großes Stück Fleisch", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 70313 / 5 * 20) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\nErfordert einen befreundeten Ruf bei den Winterpelzfurbolgs mit mindestens einem Charakter in Eurer Kriegsmeute.\n\"Das ist mal eine ordentliche Portion!\"\nVerkaufspreis:" }
entries[202315] = { ["name"] = "Gefrorener Tee", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 93750 / 5 * 20) Mana wieder her.\nIhr müsst beim Trinken sitzen bleiben.\nErfordert einen befreundeten Ruf bei den Winterpelzfurbolgs mit mindestens einem Charakter in Eurer Kriegsmeute.\n\"Schmeckt noch besser, wenn er warm und flüssig ist.\"\nVerkaufspreis:" }
